-- D04 authorized saved reports, display settings and frozen multi-report PDF snapshots.
CREATE SCHEMA reporting;REVOKE ALL ON SCHEMA reporting FROM PUBLIC;GRANT USAGE ON SCHEMA reporting TO htt_app;
CREATE TABLE reporting.saved_reports(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES core.companies(id),owner_id uuid NOT NULL REFERENCES identity.users(id),name text NOT NULL CHECK(length(btrim(name))BETWEEN 1 AND 120),visibility text NOT NULL CHECK(visibility IN('PRIVATE','COMPANY')),active boolean NOT NULL DEFAULT true,definition jsonb NOT NULL,version bigint NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(company_id,id));
CREATE TABLE reporting.saved_versions(company_id uuid NOT NULL,report_id uuid NOT NULL,version bigint NOT NULL,definition jsonb NOT NULL,name text NOT NULL,visibility text NOT NULL,active boolean NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(company_id,report_id,version),FOREIGN KEY(company_id,report_id)REFERENCES reporting.saved_reports(company_id,id));
CREATE TABLE reporting.favourites(company_id uuid NOT NULL,user_id uuid NOT NULL REFERENCES identity.users(id),report_id uuid NOT NULL,PRIMARY KEY(company_id,user_id,report_id),FOREIGN KEY(company_id,report_id)REFERENCES reporting.saved_reports(company_id,id));
CREATE TABLE reporting.preferences(company_id uuid NOT NULL REFERENCES core.companies(id),user_id uuid NOT NULL REFERENCES identity.users(id),format jsonb NOT NULL,version bigint NOT NULL DEFAULT 1,updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(company_id,user_id));
CREATE TABLE reporting.packs(id uuid PRIMARY KEY,company_id uuid NOT NULL REFERENCES core.companies(id),owner_id uuid NOT NULL REFERENCES identity.users(id),snapshot jsonb NOT NULL,sha256 text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(company_id,id),FOREIGN KEY(company_id,id)REFERENCES platform.documents(company_id,id),CHECK(sha256=encode(sha256(convert_to(snapshot::text,'UTF8')),'hex')));
DO $$DECLARE t text;BEGIN FOREACH t IN ARRAY ARRAY['saved_reports','saved_versions','favourites','preferences','packs']LOOP EXECUTE format('ALTER TABLE reporting.%I ENABLE ROW LEVEL SECURITY',t);EXECUTE format('ALTER TABLE reporting.%I FORCE ROW LEVEL SECURITY',t);EXECUTE format('CREATE POLICY company_scope ON reporting.%I USING(company_id=core.current_company())WITH CHECK(company_id=core.current_company())',t);END LOOP;END$$;
CREATE TRIGGER saved_version BEFORE UPDATE ON reporting.saved_reports FOR EACH ROW EXECUTE FUNCTION core.touch_version();
CREATE TRIGGER preferences_version BEFORE UPDATE ON reporting.preferences FOR EACH ROW EXECUTE FUNCTION core.touch_version();
CREATE TRIGGER immutable_saved_version BEFORE UPDATE OR DELETE ON reporting.saved_versions FOR EACH ROW EXECUTE FUNCTION platform.reject_mutation();
CREATE TRIGGER immutable_pack BEFORE UPDATE OR DELETE ON reporting.packs FOR EACH ROW EXECUTE FUNCTION platform.reject_mutation();
INSERT INTO identity.permissions(code,description)VALUES('reports.saved.read','Read authorized saved reports'),('reports.saved.write','Maintain own report definitions and preferences'),('reports.saved.share','Publish own company-visible definitions'),('reports.packs.create','Capture authorized private report packs');
CREATE FUNCTION identity.seed_report_designer_roles(c uuid)RETURNS void LANGUAGE sql SET search_path=pg_catalog AS $$INSERT INTO identity.role_permissions(company_id,role_id,permission_code)SELECT c,r.id,p.code FROM identity.roles r CROSS JOIN identity.permissions p WHERE r.company_id=c AND r.code IN('ADMIN','FINANCE')AND p.code IN('reports.saved.read','reports.saved.write','reports.saved.share','reports.packs.create')ON CONFLICT DO NOTHING$$;
DO $$DECLARE c uuid;BEGIN FOR c IN SELECT id FROM core.companies LOOP PERFORM set_config('htt.company_id',c::text,true);PERFORM identity.seed_report_designer_roles(c);END LOOP;PERFORM set_config('htt.company_id','',true);END$$;
CREATE FUNCTION reporting.columns(k text)RETURNS jsonb LANGUAGE sql IMMUTABLE SET search_path=pg_catalog AS $$SELECT '{"PURCHASING":[{"key":"date","label":"Date","type":"text"},{"key":"eventType","label":"Event","type":"text"},{"key":"number","label":"Document","type":"text"},{"key":"supplierId","label":"Supplier ID","type":"text"},{"key":"partyName","label":"Supplier","type":"text"},{"key":"warehouseId","label":"Warehouse ID","type":"text"},{"key":"net","label":"Net AUD","type":"decimal"},{"key":"gst","label":"GST AUD","type":"decimal"},{"key":"gross","label":"Gross AUD","type":"decimal"}],"ARAP":[{"key":"side","label":"Side","type":"text"},{"key":"partyId","label":"Party ID","type":"text"},{"key":"partyName","label":"Party","type":"text"},{"key":"opening","label":"Opening AUD","type":"decimal"},{"key":"debits","label":"Debits AUD","type":"decimal"},{"key":"credits","label":"Credits AUD","type":"decimal"},{"key":"closing","label":"Closing AUD","type":"decimal"},{"key":"businessBalance","label":"Business balance AUD","type":"decimal"},{"key":"difference","label":"Difference AUD","type":"decimal"},{"key":"advanceBalance","label":"Advance AUD","type":"decimal"}],"INVENTORY":[{"key":"positionType","label":"Position","type":"text"},{"key":"warehouseId","label":"Warehouse ID","type":"text"},{"key":"productId","label":"Product ID","type":"text"},{"key":"sku","label":"SKU","type":"text"},{"key":"name","label":"Product","type":"text"},{"key":"openingQuantity","label":"Opening qty","type":"decimal"},{"key":"quantityIn","label":"Qty in","type":"decimal"},{"key":"quantityOut","label":"Qty out","type":"decimal"},{"key":"quantity","label":"Closing qty","type":"decimal"},{"key":"openingValue","label":"Opening AUD","type":"decimal"},{"key":"valueIn","label":"Value in AUD","type":"decimal"},{"key":"valueOut","label":"Value out AUD","type":"decimal"},{"key":"value","label":"Closing AUD","type":"decimal"}],"BANKING":[{"key":"bankAccountId","label":"Bank ID","type":"text"},{"key":"bankName","label":"Bank","type":"text"},{"key":"opening","label":"Opening AUD","type":"decimal"},{"key":"debits","label":"Debits AUD","type":"decimal"},{"key":"credits","label":"Credits AUD","type":"decimal"},{"key":"closing","label":"Closing AUD","type":"decimal"},{"key":"unallocatedCash","label":"Unallocated cash AUD","type":"decimal"},{"key":"unmatchedStatements","label":"Unmatched statement AUD","type":"decimal"},{"key":"lastReconciledTo","label":"Reconciled to","type":"text"}],"SALES":[{"key":"from","label":"From","type":"text"},{"key":"to","label":"To exclusive","type":"text"},{"key":"customerId","label":"Customer ID","type":"text"},{"key":"branchId","label":"Branch ID","type":"text"},{"key":"productId","label":"Product ID","type":"text"},{"key":"sku","label":"SKU","type":"text"},{"key":"productName","label":"Product","type":"text"},{"key":"baseUomId","label":"Base UOM ID","type":"text"},{"key":"baseUnitCode","label":"Base unit","type":"text"},{"key":"net","label":"Net sales AUD","type":"decimal"},{"key":"baseQuantity","label":"Base quantity","type":"decimal"},{"key":"previousBaseQuantity","label":"Previous quantity","type":"decimal"},{"key":"yearAgoBaseQuantity","label":"Year ago quantity","type":"decimal"},{"key":"previousNet","label":"Previous net AUD","type":"decimal"},{"key":"yearAgoNet","label":"Year ago net AUD","type":"decimal"},{"key":"previousChangePercent","label":"Previous change percent","type":"decimal"},{"key":"yearChangePercent","label":"Year ago change percent","type":"decimal"}],"PROFIT_LOSS":[{"key":"code","label":"Code","type":"text"},{"key":"name","label":"Account","type":"text"},{"key":"kind","label":"Kind","type":"text"},{"key":"amount","label":"Amount AUD","type":"decimal"}],"BALANCE_SHEET":[{"key":"code","label":"Code","type":"text"},{"key":"name","label":"Account","type":"text"},{"key":"kind","label":"Kind","type":"text"},{"key":"amount","label":"Amount AUD","type":"decimal"}],"AR_AGING":[{"key":"number","label":"Document","type":"text"},{"key":"partyName","label":"Party","type":"text"},{"key":"dueOn","label":"Due date","type":"text"},{"key":"outstanding","label":"Outstanding AUD","type":"decimal"},{"key":"availableCredit","label":"Credit AUD","type":"decimal"},{"key":"netBalance","label":"Net AUD","type":"decimal"},{"key":"bucket","label":"Bucket","type":"text"}],"AP_AGING":[{"key":"number","label":"Document","type":"text"},{"key":"partyName","label":"Party","type":"text"},{"key":"dueOn","label":"Due date","type":"text"},{"key":"outstanding","label":"Outstanding AUD","type":"decimal"},{"key":"availableCredit","label":"Credit AUD","type":"decimal"},{"key":"netBalance","label":"Net AUD","type":"decimal"},{"key":"bucket","label":"Bucket","type":"text"}],"CASH_FLOW":[{"key":"postingDate","label":"Date","type":"text"},{"key":"sourceNumber","label":"Document","type":"text"},{"key":"description","label":"Description","type":"text"},{"key":"category","label":"Activity","type":"text"},{"key":"signedAmount","label":"Net AUD","type":"decimal"},{"key":"inflowContribution","label":"Inflow AUD","type":"decimal"},{"key":"outflowContribution","label":"Outflow AUD","type":"decimal"}]}'::jsonb->k$$;
CREATE FUNCTION reporting.default_columns(k text)RETURNS jsonb LANGUAGE sql IMMUTABLE SET search_path=pg_catalog AS $$SELECT '{"PURCHASING":["date","eventType","number","partyName","net","gst","gross"],"ARAP":["side","partyName","opening","debits","credits","closing","difference"],"INVENTORY":["positionType","sku","name","quantity","value"],"BANKING":["bankName","opening","debits","credits","closing","lastReconciledTo"],"SALES":["productName","baseUnitCode","baseQuantity","net","previousNet","yearAgoNet"],"PROFIT_LOSS":["code","name","kind","amount"],"BALANCE_SHEET":["code","name","kind","amount"],"AR_AGING":["number","partyName","dueOn","outstanding","availableCredit","netBalance"],"AP_AGING":["number","partyName","dueOn","outstanding","availableCredit","netBalance"],"CASH_FLOW":["postingDate","sourceNumber","description","category","signedAmount","inflowContribution"]}'::jsonb->k$$;
CREATE FUNCTION reporting.cash_flow(p_from date,p_to date)RETURNS jsonb LANGUAGE sql STABLE SET search_path=pg_catalog AS $$
WITH raw AS MATERIALIZED(SELECT l.id,l.account_id,l.debit-l.credit AS signed_amount,j.posting_date FROM accounting.journal_lines l JOIN accounting.accounts a ON a.company_id=l.company_id AND a.id=l.account_id AND a.control_kind='BANK' JOIN accounting.journal_entries j ON j.company_id=l.company_id AND j.id=l.journal_entry_id WHERE l.company_id=core.current_company() AND j.posting_date<p_to),
   cash AS MATERIALIZED(SELECT * FROM accounting.cash_flow_lines WHERE company_id=core.current_company() AND posting_date<p_to),
   flow AS MATERIALIZED(SELECT l.id AS journal_line_id,l.bank_account_id,l.journal_entry_id,l.posting_date,l.source_document_id,l.source_number,l.posting_kind,l.description,l.is_reversal,e.category,e.amount,e.signed_amount,e.basis,e.revision FROM cash l JOIN accounting.cash_flow_effective e ON e.company_id=l.company_id AND e.journal_line_id=l.id WHERE l.posting_date>=p_from),
   activity AS MATERIALIZED(SELECT category,coalesce(sum(CASE WHEN NOT is_reversal AND signed_amount>0 THEN amount WHEN is_reversal AND signed_amount<0 THEN -amount ELSE 0 END),0) AS incoming,coalesce(sum(CASE WHEN NOT is_reversal AND signed_amount<0 THEN amount WHEN is_reversal AND signed_amount>0 THEN -amount ELSE 0 END),0) AS outgoing,coalesce(sum(signed_amount),0) AS net,count(*) AS count FROM flow GROUP BY category),
   amounts AS(SELECT coalesce(sum(signed_amount)FILTER(WHERE posting_date<p_from),0) AS opening,coalesce(sum(signed_amount),0) AS closing FROM cash),
   controls AS(SELECT coalesce(sum(signed_amount),0) AS all_bank_closing,coalesce(sum(r.signed_amount)FILTER(WHERE sc.included=false),0) AS excluded_closing,(SELECT count(*) FROM accounting.bank_accounts b LEFT JOIN accounting.cash_flow_scopes s ON s.company_id=b.company_id AND s.bank_account_id=b.id WHERE b.company_id=core.current_company() AND s.bank_account_id IS NULL) AS missing_scope,(SELECT count(*) FROM accounting.cash_flow_scopes s WHERE s.company_id=core.current_company() AND s.review_required AND EXISTS(SELECT 1 FROM raw r WHERE r.account_id=s.bank_account_id)) AS pending_scope,
    (SELECT count(*) FROM cash l WHERE l.posting_date>=p_from AND l.amount<>(SELECT coalesce(sum(amount),0) FROM flow f WHERE f.journal_line_id=l.id)) AS allocation_errors FROM raw r LEFT JOIN accounting.cash_flow_scopes sc ON sc.company_id=core.current_company() AND sc.bank_account_id=r.account_id),
   banks AS MATERIALIZED(SELECT b.id,b.name,b.kind,b.active,a.code,sc.included,sc.review_required,coalesce((SELECT sum(signed_amount) FROM raw WHERE account_id=b.id AND posting_date<p_from),0) AS opening,coalesce((SELECT sum(signed_amount) FROM raw WHERE account_id=b.id),0) AS closing,EXISTS(SELECT 1 FROM raw WHERE account_id=b.id) AS used,
    br.id AS reconciliation_id,br.to_date AS reconciled_through,br.closing_balance AS statement_closing,br.book_closing AS snapshot_book,br.outstanding_deposits,br.outstanding_payments,
    (SELECT coalesce(sum(l.debit-l.credit),0) FROM accounting.journal_lines l JOIN accounting.journal_entries j ON j.company_id=l.company_id AND j.id=l.journal_entry_id WHERE l.company_id=core.current_company() AND l.account_id=b.id AND j.posting_date<=br.to_date) AS current_book_at_reconciliation
    FROM accounting.bank_accounts b JOIN accounting.accounts a ON a.company_id=b.company_id AND a.id=b.id LEFT JOIN accounting.cash_flow_scopes sc ON sc.company_id=b.company_id AND sc.bank_account_id=b.id LEFT JOIN LATERAL(SELECT * FROM accounting.active_bank_reconciliations r WHERE r.company_id=b.company_id AND r.bank_account_id=b.id AND r.to_date<p_to ORDER BY r.to_date DESC,r.id DESC LIMIT 1)br ON true WHERE b.company_id=core.current_company()),
   bank_status AS(SELECT count(*)FILTER(WHERE (used OR reconciliation_id IS NOT NULL) AND kind<>'CASH') AS eligible,count(*)FILTER(WHERE (used OR reconciliation_id IS NOT NULL) AND kind<>'CASH' AND reconciliation_id IS NOT NULL) AS available,count(*)FILTER(WHERE (used OR reconciliation_id IS NOT NULL) AND kind<>'CASH' AND reconciled_through=p_to::date-1) AS matched,count(*)FILTER(WHERE reconciliation_id IS NOT NULL AND(current_book_at_reconciliation<>snapshot_book OR current_book_at_reconciliation-outstanding_deposits+outstanding_payments<>statement_closing)) AS errors FROM banks),
   totals AS(SELECT m.*,c.*,b.*,coalesce((SELECT net FROM activity WHERE category='OPERATING'),0) AS operating,coalesce((SELECT net FROM activity WHERE category='INVESTING'),0) AS investing,coalesce((SELECT net FROM activity WHERE category='FINANCING'),0) AS financing,coalesce((SELECT net FROM activity WHERE category='INTERNAL'),0) AS internal,coalesce((SELECT net FROM activity WHERE category='UNCLASSIFIED'),0) AS unclassified,coalesce((SELECT count FROM activity WHERE category='UNCLASSIFIED'),0) AS unclassified_count,(SELECT count(*) FROM flow) AS count FROM amounts m CROSS JOIN controls c CROSS JOIN bank_status b),
   assessed AS(SELECT *,closing-opening-operating-investing-financing-internal-unclassified AS movement_difference,closing-(all_bank_closing-excluded_closing) AS bank_scope_difference FROM totals),
   paged AS(SELECT * FROM flow ORDER BY posting_date,journal_entry_id,journal_line_id,category LIMIT 1001 OFFSET 0)
   SELECT jsonb_build_object('companyId',core.current_company(),'currency','AUD','method','DIRECT','snapshotAt',statement_timestamp(),'from',p_from,'to',p_to,'page',1,'pageSize',1001,'totalCount',t.count,
    'status',CASE WHEN movement_difference<>0 OR bank_scope_difference<>0 OR internal<>0 OR allocation_errors>0 OR missing_scope>0 OR errors>0 THEN 'UNRECONCILED' WHEN unclassified_count>0 OR pending_scope>0 THEN 'INCOMPLETE' ELSE 'READY' END,
    'classificationStatus',CASE WHEN unclassified_count=0 AND allocation_errors=0 AND pending_scope=0 THEN 'COMPLETE' ELSE 'INCOMPLETE' END,
    'ledgerStatus',CASE WHEN movement_difference=0 AND bank_scope_difference=0 AND internal=0 AND allocation_errors=0 AND missing_scope=0 THEN 'RECONCILED' ELSE 'UNRECONCILED' END,
    'bankStatus',CASE WHEN errors>0 THEN 'UNRECONCILED' WHEN available=0 THEN 'NOT_AVAILABLE' WHEN matched<eligible THEN 'PARTIAL' ELSE 'RECONCILED' END,
    'totals',jsonb_build_object('openingCash',opening::text,'operatingNet',operating::text,'investingNet',investing::text,'financingNet',financing::text,'classifiedNetChange',(operating+investing+financing)::text,'unclassifiedNet',unclassified::text,'internalNet',internal::text,'netChange',(closing-opening)::text,'closingCash',closing::text,'movementDifference',movement_difference::text,'allBankClosing',all_bank_closing::text,'excludedBankClosing',excluded_closing::text,'bankScopeDifference',bank_scope_difference::text,'unclassifiedCount',unclassified_count,'allocationErrorCount',allocation_errors,'missingScopeCount',missing_scope,'scopeReviewRequiredCount',pending_scope),
    'activities',coalesce((SELECT jsonb_agg(jsonb_build_object('category',category,'inflow',incoming::text,'outflow',outgoing::text,'net',net::text,'allocationCount',count)ORDER BY category) FROM activity),'[]'::jsonb),
    'banks',coalesce((SELECT jsonb_agg(jsonb_build_object('bankAccountId',id,'code',code,'name',name,'kind',kind,'active',active,'included',included,'scopeReviewRequired',review_required,'openingSigned',opening::text,'closingSigned',closing::text,'reconciliationId',reconciliation_id,'reconciledThrough',reconciled_through,'statementClosing',statement_closing::text,'snapshotBookClosing',snapshot_book::text,'currentBookAtReconciliation',CASE WHEN reconciliation_id IS NOT NULL THEN current_book_at_reconciliation::text END,'outstandingDeposits',outstanding_deposits::text,'outstandingPayments',outstanding_payments::text,'reconciliationDifference',CASE WHEN reconciliation_id IS NOT NULL THEN(current_book_at_reconciliation-outstanding_deposits+outstanding_payments-statement_closing)::text END)ORDER BY code,id) FROM banks),'[]'::jsonb),
    'items',coalesce((SELECT jsonb_agg(jsonb_build_object('journalLineId',journal_line_id,'bankAccountId',bank_account_id,'journalId',journal_entry_id,'postingDate',posting_date,'sourceDocumentId',source_document_id,'sourceNumber',source_number,'postingKind',posting_kind,'description',description,'category',category,'amount',amount::text,'signedAmount',signed_amount::text,'isReversal',is_reversal,'inflowContribution',(CASE WHEN NOT is_reversal AND signed_amount>0 THEN amount WHEN is_reversal AND signed_amount<0 THEN -amount ELSE 0 END)::text,'outflowContribution',(CASE WHEN NOT is_reversal AND signed_amount<0 THEN amount WHEN is_reversal AND signed_amount>0 THEN -amount ELSE 0 END)::text,'basis',basis,'classificationRevision',revision)ORDER BY posting_date,journal_entry_id,journal_line_id,category) FROM paged),'[]'::jsonb)) AS result FROM assessed t
$$;
CREATE FUNCTION reporting.require_definition(p_def jsonb)RETURNS void LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE v_kind text:=p_def->>'kind';v_f jsonb:=p_def->'filters';v_from date;v_to date;v_asof date;v_key text;v_cols jsonb;BEGIN
 PERFORM crm.require_mobile('reports.saved.read');
 IF p_def IS NULL OR jsonb_typeof(p_def)<>'object'OR octet_length(p_def::text)>16384 OR v_kind IS NULL OR reporting.columns(v_kind)IS NULL OR jsonb_typeof(v_f)IS DISTINCT FROM'object'OR EXISTS(SELECT 1 FROM jsonb_object_keys(p_def)a(key)WHERE a.key NOT IN('kind','filters','columns'))THEN RAISE EXCEPTION 'Invalid report definition' USING ERRCODE='HR422';END IF;
 IF v_kind IN('PROFIT_LOSS','BALANCE_SHEET','AR_AGING','AP_AGING','CASH_FLOW')THEN
  PERFORM crm.require_mobile('accounting.reports.read');PERFORM crm.require_mobile('accounting.ledger.read');
  IF v_kind='CASH_FLOW'THEN PERFORM crm.require_mobile('accounting.banks.read');END IF;
 ELSE PERFORM accounting.require_operating_report(v_kind);END IF;
 FOR v_key IN SELECT key FROM jsonb_object_keys(v_f)a(key)LOOP
  IF NOT((v_key IN('from','to')AND v_kind NOT IN('BALANCE_SHEET','AR_AGING','AP_AGING'))OR(v_key='asOf'AND v_kind IN('BALANCE_SHEET','AR_AGING','AP_AGING'))OR(v_key='partyId'AND v_kind IN('AR_AGING','AP_AGING','PURCHASING','ARAP'))OR(v_key='warehouseId'AND v_kind='INVENTORY')OR(v_key='bankAccountId'AND v_kind='BANKING'))THEN RAISE EXCEPTION 'Filter is not supported by this source' USING ERRCODE='HR422';END IF;
 END LOOP;
 IF v_kind IN('BALANCE_SHEET','AR_AGING','AP_AGING')THEN
  IF coalesce(v_f->>'asOf','')!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}$'THEN RAISE EXCEPTION 'Explicit ISO asOf required' USING ERRCODE='HR422';END IF;v_asof:=(v_f->>'asOf')::date;IF v_asof<date '0003-01-01'THEN RAISE EXCEPTION 'Invalid asOf' USING ERRCODE='HR422';END IF;
 ELSE
  IF coalesce(v_f->>'from','')!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}$'OR coalesce(v_f->>'to','')!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}$'THEN RAISE EXCEPTION 'Explicit ISO range required' USING ERRCODE='HR422';END IF;
  v_from:=(v_f->>'from')::date;v_to:=(v_f->>'to')::date;IF v_from<date '0003-01-01'OR v_to<=v_from OR v_to-v_from>366 THEN RAISE EXCEPTION 'Use half-open interval 1-366 days' USING ERRCODE='HR422';END IF;
 END IF;
 IF v_f->>'partyId'IS NOT NULL AND NOT EXISTS(SELECT 1 FROM crm.parties q WHERE q.company_id=core.current_company()AND q.id=(v_f->>'partyId')::uuid)THEN RAISE EXCEPTION 'Party unavailable' USING ERRCODE='HT404';END IF;
 IF v_f->>'warehouseId'IS NOT NULL AND NOT EXISTS(SELECT 1 FROM catalog.warehouses q WHERE q.company_id=core.current_company()AND q.id=(v_f->>'warehouseId')::uuid)THEN RAISE EXCEPTION 'Warehouse unavailable' USING ERRCODE='HT404';END IF;
 IF v_f->>'bankAccountId'IS NOT NULL AND NOT EXISTS(SELECT 1 FROM accounting.bank_accounts q WHERE q.company_id=core.current_company()AND q.id=(v_f->>'bankAccountId')::uuid)THEN RAISE EXCEPTION 'Bank unavailable' USING ERRCODE='HT404';END IF;
 v_cols:=coalesce(p_def->'columns',reporting.default_columns(v_kind));
 IF jsonb_typeof(v_cols)<>'array'OR jsonb_array_length(v_cols)NOT BETWEEN 1 AND 8 OR EXISTS(SELECT 1 FROM jsonb_array_elements(v_cols)a(value)WHERE jsonb_typeof(a.value)<>'string'OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(reporting.columns(v_kind))c(value)WHERE c.value->>'key'=a.value#>>'{}'))OR EXISTS(SELECT 1 FROM jsonb_array_elements(v_cols)a(value)GROUP BY a.value HAVING count(*)>1)THEN RAISE EXCEPTION 'Select 1-8 distinct source columns' USING ERRCODE='HR422';END IF;
 EXCEPTION WHEN invalid_parameter_value OR invalid_text_representation OR invalid_datetime_format OR datetime_field_overflow THEN RAISE EXCEPTION 'Invalid source date or identifier' USING ERRCODE='HR422';
END$$;
CREATE FUNCTION reporting.can_definition(p_def jsonb)RETURNS boolean LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$BEGIN PERFORM reporting.require_definition(p_def);RETURN true;EXCEPTION WHEN insufficient_privilege OR SQLSTATE 'HT404' OR SQLSTATE 'HR422' THEN RETURN false;END$$;
CREATE FUNCTION reporting.format(p_input jsonb)RETURNS jsonb LANGUAGE plpgsql IMMUTABLE SET search_path=pg_catalog AS $$DECLARE v jsonb:='{"currency":"AUD","basis":"SOURCE_DEFINED","decimalPlaces":2,"negativeStyle":"MINUS","header":"","footer":""}'::jsonb||coalesce(p_input,'{}');BEGIN
 IF jsonb_typeof(v)<>'object'OR EXISTS(SELECT 1 FROM jsonb_object_keys(v)a(key)WHERE a.key NOT IN('currency','basis','decimalPlaces','negativeStyle','header','footer'))OR v->>'currency'IS DISTINCT FROM'AUD'OR v->>'basis'IS DISTINCT FROM'SOURCE_DEFINED'OR v->'decimalPlaces'NOT IN('0','2')OR coalesce(v->>'negativeStyle','')NOT IN('MINUS','PARENTHESES')OR jsonb_typeof(v->'header')IS DISTINCT FROM'string'OR jsonb_typeof(v->'footer')IS DISTINCT FROM'string'OR length(v->>'header')>120 OR length(v->>'footer')>240 OR(v->>'header')~'[[:cntrl:]]'OR(v->>'footer')~'[[:cntrl:]]'THEN RAISE EXCEPTION 'Use AUD, native source basis and supported display formatting' USING ERRCODE='HR422';END IF;RETURN v;
 EXCEPTION WHEN invalid_parameter_value THEN RAISE EXCEPTION 'Invalid formatting object' USING ERRCODE='HR422';
END$$;
CREATE FUNCTION reporting.preferences(p_expected bigint,p_input jsonb DEFAULT NULL)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE v reporting.preferences;v_format jsonb;BEGIN
 PERFORM crm.require_mobile('reports.saved.read');
 IF p_input IS NOT NULL THEN
  PERFORM crm.require_mobile('reports.saved.write');v_format:=reporting.format(p_input);PERFORM pg_advisory_xact_lock(hashtextextended('report-settings:'||core.current_company()::text||':'||core.current_actor()::text,0));
  SELECT*INTO v FROM reporting.preferences q WHERE q.company_id=core.current_company()AND q.user_id=core.current_actor()FOR UPDATE;
  IF coalesce(v.version,0)IS DISTINCT FROM p_expected THEN RAISE EXCEPTION 'Settings changed' USING ERRCODE='HR409';END IF;
  INSERT INTO reporting.preferences(company_id,user_id,format)VALUES(core.current_company(),core.current_actor(),v_format)ON CONFLICT(company_id,user_id)DO UPDATE SET format=excluded.format;
 END IF;
 SELECT*INTO v FROM reporting.preferences q WHERE q.company_id=core.current_company()AND q.user_id=core.current_actor();RETURN jsonb_build_object('version',coalesce(v.version,0),'format',coalesce(v.format,reporting.format(NULL)));
END$$;
CREATE FUNCTION reporting.saved_view(p_id uuid)RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE v reporting.saved_reports;BEGIN
 SELECT*INTO v FROM reporting.saved_reports q WHERE q.company_id=core.current_company()AND q.id=p_id;
 IF NOT FOUND OR NOT(v.owner_id=core.current_actor()OR(v.active AND v.visibility='COMPANY'))THEN RAISE EXCEPTION 'Saved report unavailable' USING ERRCODE='HT404';END IF;PERFORM reporting.require_definition(v.definition);
 RETURN jsonb_build_object('id',v.id,'ownerId',v.owner_id,'name',v.name,'visibility',v.visibility,'active',v.active,'version',v.version,'definition',v.definition,'favourite',EXISTS(SELECT 1 FROM reporting.favourites q WHERE q.company_id=v.company_id AND q.report_id=v.id AND q.user_id=core.current_actor()));
END$$;
CREATE FUNCTION reporting.save(p_id uuid,p_expected bigint,p_name text,p_visibility text,p_active boolean,p_def jsonb)RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE v_id uuid:=coalesce(p_id,gen_random_uuid());v_old reporting.saved_reports;BEGIN
 PERFORM crm.require_mobile('reports.saved.write');PERFORM reporting.require_definition(p_def);
 IF p_name IS NULL OR length(btrim(p_name))NOT BETWEEN 1 AND 120 OR p_visibility IS NULL OR p_visibility NOT IN('PRIVATE','COMPANY')OR p_active IS NULL THEN RAISE EXCEPTION 'Invalid saved report metadata' USING ERRCODE='HR422';END IF;
 IF p_visibility='COMPANY'THEN PERFORM crm.require_mobile('reports.saved.share');END IF;
 IF p_id IS NULL THEN INSERT INTO reporting.saved_reports(id,company_id,owner_id,name,visibility,active,definition)VALUES(v_id,core.current_company(),core.current_actor(),btrim(p_name),p_visibility,p_active,p_def);
 ELSE
  SELECT*INTO v_old FROM reporting.saved_reports q WHERE q.company_id=core.current_company()AND q.id=p_id FOR UPDATE;
  IF NOT FOUND OR v_old.owner_id<>core.current_actor()THEN RAISE EXCEPTION 'Only owner may maintain this saved report' USING ERRCODE='HT404';END IF;
  IF p_expected IS DISTINCT FROM v_old.version THEN RAISE EXCEPTION 'Saved report changed' USING ERRCODE='HR409';END IF;
  UPDATE reporting.saved_reports SET name=btrim(p_name),visibility=p_visibility,active=p_active,definition=p_def WHERE id=p_id;
 END IF;
 INSERT INTO reporting.saved_versions(company_id,report_id,version,definition,name,visibility,active)SELECT company_id,id,version,definition,name,visibility,active FROM reporting.saved_reports WHERE company_id=core.current_company()AND id=v_id;
 RETURN v_id;
END$$;
CREATE FUNCTION reporting.favourite(p_id uuid,p_active boolean)RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$BEGIN
 PERFORM reporting.saved_view(p_id);IF p_active IS NULL THEN RAISE EXCEPTION 'Favourite flag required' USING ERRCODE='HR422';END IF;
 IF p_active THEN INSERT INTO reporting.favourites(company_id,user_id,report_id)VALUES(core.current_company(),core.current_actor(),p_id)ON CONFLICT DO NOTHING;
 ELSE DELETE FROM reporting.favourites WHERE company_id=core.current_company()AND user_id=core.current_actor()AND report_id=p_id;END IF;
END$$;
CREATE FUNCTION reporting.saved_list(p_favourites boolean,p_size int,p_offset int)RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$BEGIN
 PERFORM crm.require_mobile('reports.saved.read');IF p_size IS NULL OR p_offset IS NULL OR p_size NOT BETWEEN 1 AND 100 OR p_offset NOT BETWEEN 0 AND 10000000 THEN RAISE EXCEPTION 'Invalid report page' USING ERRCODE='HR422';END IF;
 RETURN(WITH visible AS MATERIALIZED(SELECT q.id,q.name FROM reporting.saved_reports q WHERE q.company_id=core.current_company()AND q.active AND(q.owner_id=core.current_actor()OR q.visibility='COMPANY')AND reporting.can_definition(q.definition)AND(NOT coalesce(p_favourites,false)OR EXISTS(SELECT 1 FROM reporting.favourites f WHERE f.company_id=q.company_id AND f.report_id=q.id AND f.user_id=core.current_actor())))SELECT jsonb_build_object('totalCount',count(*),'items',(SELECT coalesce(jsonb_agg(reporting.saved_view(id)ORDER BY name,id),'[]')FROM(SELECT*FROM visible ORDER BY name,id LIMIT p_size OFFSET p_offset)z))FROM visible);
END$$;
CREATE FUNCTION reporting.section(p_def jsonb)RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE v_kind text:=p_def->>'kind';v_f jsonb:=p_def->'filters';v_body jsonb;v_rows jsonb;v_selected jsonb;v_columns jsonb;v_meta jsonb;BEGIN
 PERFORM reporting.require_definition(p_def);
 CASE v_kind
 WHEN'PROFIT_LOSS'THEN v_body:=workbench.profit_loss((v_f->>'from')::date,(v_f->>'to')::date);
 WHEN'BALANCE_SHEET'THEN v_body:=workbench.balance_sheet((v_f->>'asOf')::date);
 WHEN'AR_AGING'THEN v_body:=workbench.aging('AR',(v_f->>'asOf')::date,(v_f->>'partyId')::uuid,1001,0);
 WHEN'AP_AGING'THEN v_body:=workbench.aging('AP',(v_f->>'asOf')::date,(v_f->>'partyId')::uuid,1001,0);
 WHEN'CASH_FLOW'THEN v_body:=reporting.cash_flow((v_f->>'from')::date,(v_f->>'to')::date);
 ELSE v_body:=accounting.operating_report(v_kind,(v_f->>'from')::date,(v_f->>'to')::date,(v_f->>'partyId')::uuid,(v_f->>'warehouseId')::uuid,(v_f->>'bankAccountId')::uuid);
 END CASE;
 v_rows:=coalesce(v_body->'rows',v_body->'items','[]');
 IF jsonb_array_length(v_rows)>1000 OR coalesce((v_body->>'totalCount')::bigint,0)>1000 THEN RAISE EXCEPTION 'Source exceeds 1000 rows; narrow report' USING ERRCODE='HR422';END IF;
 v_selected:=coalesce(p_def->'columns',reporting.default_columns(v_kind));
 SELECT jsonb_agg(c.value ORDER BY keys.n)INTO v_columns FROM jsonb_array_elements_text(v_selected)WITH ORDINALITY keys(key,n)JOIN jsonb_array_elements(reporting.columns(v_kind))c(value)ON c.value->>'key'=keys.key;
 SELECT coalesce(jsonb_agg((SELECT jsonb_object_agg(keys.key,rowdata.value->keys.key)FROM jsonb_array_elements_text(v_selected)keys(key))ORDER BY rowdata.n),'[]')INTO v_rows FROM jsonb_array_elements(v_rows)WITH ORDINALITY rowdata(value,n);
 SELECT coalesce(jsonb_object_agg(m.key,m.value),'{}')INTO v_meta FROM jsonb_each(v_body)m WHERE m.key IN('currency','basis','method','from','to','asOf','fiscalYearStart','totals','status','bankStatus','advanceControl','companyInventoryDifference','controlCheckScope','clearingBasis','reconciliation','activities');
 RETURN jsonb_build_object('kind',v_kind,'definition',p_def,'columns',v_columns,'rows',v_rows,'metadata',v_meta);
END$$;
CREATE FUNCTION reporting.resolve(p_item jsonb)RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE v_saved jsonb;BEGIN
 IF p_item->>'savedReportId'IS NOT NULL THEN
  IF EXISTS(SELECT 1 FROM jsonb_object_keys(p_item)q(key)WHERE q.key NOT IN('savedReportId','version'))THEN RAISE EXCEPTION 'Do not override a saved definition' USING ERRCODE='HR422';END IF;
  v_saved:=reporting.saved_view((p_item->>'savedReportId')::uuid);IF v_saved->'active'IS DISTINCT FROM'true'::jsonb OR(v_saved->>'version')::bigint IS DISTINCT FROM(p_item->>'version')::bigint THEN RAISE EXCEPTION 'Saved report version changed or archived' USING ERRCODE='HR409';END IF;RETURN v_saved->'definition';
 END IF;
 IF p_item IS NULL OR jsonb_typeof(p_item)<>'object'OR p_item->'definition'IS NULL OR EXISTS(SELECT 1 FROM jsonb_object_keys(p_item)q(key)WHERE q.key<>'definition')THEN RAISE EXCEPTION 'Use a saved version or inline definition' USING ERRCODE='HR422';END IF;
 RETURN p_item->'definition';
 EXCEPTION WHEN invalid_text_representation THEN RAISE EXCEPTION 'Invalid report reference' USING ERRCODE='HR422';
END$$;
CREATE FUNCTION reporting.snapshot(p_title text,p_items jsonb,p_format jsonb)RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE v_item jsonb;v_section jsonb;v_sections jsonb:='[]';v_format jsonb;v_count int:=0;BEGIN
 PERFORM crm.require_mobile('reports.packs.create');PERFORM crm.require_mobile('reports.saved.read');
 IF p_title IS NULL OR length(btrim(p_title))NOT BETWEEN 1 AND 120 OR p_title~'[[:cntrl:]]'OR p_items IS NULL OR jsonb_typeof(p_items)<>'array'OR jsonb_array_length(p_items)NOT BETWEEN 1 AND 8 THEN RAISE EXCEPTION 'Use title and 1-8 reports' USING ERRCODE='HR422';END IF;
 v_format:=reporting.format(p_format);
 FOR v_item IN SELECT value FROM jsonb_array_elements(p_items)LOOP
  v_section:=reporting.section(reporting.resolve(v_item));v_count:=v_count+jsonb_array_length(v_section->'rows');v_sections:=v_sections||jsonb_build_array(v_section);
 END LOOP;
 IF v_count>2000 THEN RAISE EXCEPTION 'Pack exceeds 2000 rows; split pack' USING ERRCODE='HR422';END IF;
 RETURN jsonb_build_object('templateVersion',3,'title',btrim(p_title),'companyId',core.current_company(),'issuer',(SELECT jsonb_build_object('name',name,'abn',abn)FROM core.companies WHERE id=core.current_company()),'snapshotAt',statement_timestamp(),'mvccSnapshot',pg_current_snapshot()::text,'format',v_format,'sections',v_sections);
END$$;
CREATE FUNCTION reporting.capture(p_title text,p_items jsonb)RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE v_id uuid:=gen_random_uuid();v_body jsonb;BEGIN
 SELECT reporting.snapshot(p_title,p_items,(reporting.preferences(NULL,NULL))->'format')INTO v_body;
 v_body:=v_body||jsonb_build_object('filename','PACK-'||v_id::text||'.pdf');IF octet_length(v_body::text)>400000 THEN RAISE EXCEPTION 'Pack exceeds bounded PDF input; narrow selection' USING ERRCODE='HR422';END IF;
 INSERT INTO platform.documents(id,company_id,document_type,number,business_date,state,created_by)VALUES(v_id,core.current_company(),'REPORT_PACK','PACK-'||v_id::text,(SELECT(now()AT TIME ZONE timezone)::date FROM core.companies WHERE id=core.current_company()),'CONFIRMED',core.current_actor());
 INSERT INTO reporting.packs(id,company_id,owner_id,snapshot,sha256)VALUES(v_id,core.current_company(),core.current_actor(),v_body,encode(sha256(convert_to(v_body::text,'UTF8')),'hex'));RETURN v_id;
END$$;
CREATE FUNCTION reporting.pack_view(p_id uuid)RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE v reporting.packs;v_section jsonb;BEGIN
 PERFORM crm.require_mobile('reports.packs.create');SELECT*INTO v FROM reporting.packs q WHERE q.company_id=core.current_company()AND q.id=p_id AND q.owner_id=core.current_actor();
 IF NOT FOUND OR NOT platform.document_visible(p_id)THEN RAISE EXCEPTION 'Report pack unavailable' USING ERRCODE='HT404';END IF;
 FOR v_section IN SELECT value FROM jsonb_array_elements(v.snapshot->'sections')LOOP PERFORM reporting.require_definition(v_section->'definition');END LOOP;
 RETURN jsonb_build_object('id',v.id,'version',1,'sha256',v.sha256,'snapshot',v.snapshot,'createdAt',v.created_at);
END$$;
CREATE INDEX pack_owner_history ON reporting.packs(company_id,owner_id,created_at DESC,id);
CREATE FUNCTION reporting.pack_list(p_size int,p_offset int)RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$BEGIN
 PERFORM crm.require_mobile('reports.packs.create');PERFORM crm.require_mobile('reports.saved.read');
 IF p_size IS NULL OR p_offset IS NULL OR p_size NOT BETWEEN 1 AND 100 OR p_offset NOT BETWEEN 0 AND 10000000 THEN RAISE EXCEPTION 'Invalid pack page' USING ERRCODE='HR422';END IF;
 RETURN(WITH visible AS MATERIALIZED(SELECT q.id,q.snapshot->>'title'AS title,q.sha256,q.created_at,jsonb_array_length(q.snapshot->'sections')AS sections FROM reporting.packs q WHERE q.company_id=core.current_company()AND q.owner_id=core.current_actor()AND platform.document_visible(q.id)AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(q.snapshot->'sections')item(value)WHERE NOT reporting.can_definition(item.value->'definition')))
 SELECT jsonb_build_object('totalCount',count(*),'items',(SELECT coalesce(jsonb_agg(jsonb_build_object('id',z.id,'title',z.title,'sha256',z.sha256,'createdAt',z.created_at,'sectionCount',z.sections,'version',1)ORDER BY z.created_at DESC,z.id),'[]')FROM(SELECT*FROM visible ORDER BY created_at DESC,id LIMIT p_size OFFSET p_offset)z))FROM visible);
END$$;
-- Integrate existing private file/job/retry workflow; do not widen email or attachment rights.
ALTER FUNCTION platform.require_document_access(uuid,text)RENAME TO require_document_access_before_packs;
CREATE FUNCTION platform.require_document_access(doc uuid,action text)RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$BEGIN
 IF EXISTS(SELECT 1 FROM platform.documents WHERE company_id=core.current_company()AND id=doc AND document_type='REPORT_PACK')THEN
  IF action NOT IN('READ','PDF')THEN RAISE EXCEPTION 'Report packs support authorized PDF only' USING ERRCODE='HD422';END IF;
  PERFORM reporting.pack_view(doc);PERFORM crm.require_mobile(CASE WHEN action='READ'THEN'documents.files.read'ELSE'documents.pdf.request'END);RETURN'REPORT_PACK';
 END IF;RETURN platform.require_document_access_before_packs(doc,action);
END$$;
CREATE FUNCTION reporting.guard_pack_job()RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE v_expected jsonb;BEGIN
 IF EXISTS(SELECT 1 FROM platform.documents WHERE company_id=NEW.company_id AND id=NEW.document_id AND document_type='REPORT_PACK')THEN
  PERFORM platform.require_document_access(NEW.document_id,'PDF');SELECT snapshot||jsonb_build_object('snapshotHash',sha256)INTO v_expected FROM reporting.packs WHERE company_id=NEW.company_id AND id=NEW.document_id;
  IF NEW.kind<>'PDF'OR NEW.source_version<>1 OR NEW.payload IS DISTINCT FROM v_expected THEN RAISE EXCEPTION 'Pack PDF must match frozen source' USING ERRCODE='23514';END IF;
 END IF;RETURN NEW;
END$$;
CREATE TRIGGER pack_job_source BEFORE INSERT ON platform.document_jobs FOR EACH ROW EXECUTE FUNCTION reporting.guard_pack_job();
ALTER FUNCTION platform.finish_document_work(uuid,uuid,text,text,bytea,text)RENAME TO finish_document_work_before_packs;
-- PL/pgSQL parameter qualifiers use the function label; rename that label in the private copy as well.
DO $$DECLARE v_sql text;BEGIN SELECT pg_get_functiondef('platform.finish_document_work_before_packs(uuid,uuid,text,text,bytea,text)'::regprocedure)INTO v_sql;EXECUTE replace(v_sql,'finish_document_work.','finish_document_work_before_packs.');END$$;
CREATE FUNCTION platform.finish_document_work(jid uuid,fence uuid,result text,error_code text,pdf bytea DEFAULT NULL,provider text DEFAULT NULL)RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE v_job platform.document_jobs;v_result text:=result;v_error text:=error_code;BEGIN
 SELECT*INTO v_job FROM platform.document_jobs WHERE id=jid AND state='PROCESSING'AND lease_token=fence AND lease_until>now();IF NOT FOUND THEN RETURN false;END IF;
 PERFORM set_config('htt.company_id',v_job.company_id::text,true);PERFORM set_config('htt.actor_id',v_job.created_by::text,true);
 IF result='SUCCEEDED'AND EXISTS(SELECT 1 FROM reporting.packs WHERE company_id=v_job.company_id AND id=v_job.document_id)THEN
  BEGIN PERFORM platform.require_document_access(v_job.document_id,'PDF');EXCEPTION WHEN insufficient_privilege OR SQLSTATE 'HT404' THEN v_result:='FAILED';v_error:='document_access_changed';END;
 END IF;
 RETURN platform.finish_document_work_before_packs(jid,fence,v_result,v_error,pdf,provider);
END$$;
CREATE FUNCTION reporting.guard_pack_registry()RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$BEGIN IF EXISTS(SELECT 1 FROM reporting.packs WHERE company_id=OLD.company_id AND id=OLD.id)THEN RAISE EXCEPTION 'Frozen pack registry is immutable' USING ERRCODE='23514';END IF;IF TG_OP='DELETE'THEN RETURN OLD;END IF;RETURN NEW;END$$;
CREATE TRIGGER frozen_pack_registry BEFORE UPDATE OR DELETE ON platform.documents FOR EACH ROW EXECUTE FUNCTION reporting.guard_pack_registry();
REVOKE ALL ON ALL TABLES IN SCHEMA reporting FROM PUBLIC,htt_app,htt_worker,htt_portal;
REVOKE ALL ON ALL FUNCTIONS IN SCHEMA reporting FROM PUBLIC;
REVOKE ALL ON FUNCTION identity.seed_report_designer_roles(uuid),platform.require_document_access_before_packs(uuid,text),platform.finish_document_work_before_packs(uuid,uuid,text,text,bytea,text),platform.require_document_access(uuid,text),platform.finish_document_work(uuid,uuid,text,text,bytea,text)FROM PUBLIC;
-- Renamed routines retain old grants unless explicitly removed.
REVOKE ALL ON FUNCTION platform.require_document_access_before_packs(uuid,text),platform.finish_document_work_before_packs(uuid,uuid,text,text,bytea,text)FROM htt_app,htt_worker,htt_portal;
GRANT EXECUTE ON FUNCTION platform.require_document_access(uuid,text)TO htt_app;
GRANT EXECUTE ON FUNCTION platform.finish_document_work(uuid,uuid,text,text,bytea,text)TO htt_worker;
GRANT EXECUTE ON FUNCTION reporting.pack_list(integer,integer),reporting.require_definition(jsonb),reporting.resolve(jsonb),reporting.snapshot(text,jsonb,jsonb),reporting.preferences(bigint,jsonb),reporting.saved_view(uuid),reporting.save(uuid,bigint,text,text,boolean,jsonb),reporting.favourite(uuid,boolean),reporting.saved_list(boolean,integer,integer),reporting.capture(text,jsonb),reporting.pack_view(uuid)TO htt_app;
